const historyData = $input.first().json;
const prev = $('Wait 150s for Image').item.json;
const promptId = prev.prompt_id;

if (!historyData || !historyData[promptId]) {
  throw new Error(`No history entry found for prompt ${promptId}. Image may still be generating.`);
}

const outputs = historyData[promptId].outputs;
if (!outputs) throw new Error(`No outputs in history for prompt ${promptId}`);

let imageFilename = null;
for (const output of Object.values(outputs)) {
  if (output.images && output.images.length > 0) {
    imageFilename = output.images[0].filename;
    break;
  }
}

if (!imageFilename) throw new Error('No image filename found in ComfyUI history');

const profile = $('Assemble Full Resume').item.json;

return [{ json: {
  ...profile,
  imageFilename,
  imageUrl: `http://YOUR_COMFYUI_URL/view?filename=${imageFilename}`
}}];

