const item = $input.first();
const meta = $('Parse Create + Build Patch').item.json;

// 1. Generate filenames
const safeName = (meta.candidateName || 'resume').replace(/[^a-zA-Z0-9_-]/g, '_');
const ts = new Date().toISOString().slice(0,10);
const pdfFileName = `${safeName}_${ts}.pdf`;
const jsonFileName = `${safeName}_${ts}.json`;

// 2. Determine Drive folder
const driveFolder = (meta.category || '').toUpperCase().startsWith('CS') ? 'CS' : 'Engineering';

// 3. Prepare JSON content
const jsonContent = JSON.stringify(meta.resumeData || {}, null, 2);

// 4. Return both binary objects
// Note: We use 'pdfBinary' for the PDF and 'jsonBinary' for the JSON
return [{
  json: {
    ...meta,
    pdfFileName,
    jsonFileName,
    driveFolder,
  },
  binary: {
    // Keep the PDF from the previous node (HTTP: Download PDF)
    pdfBinary: item.binary.pdfBinary,
    // Create the new JSON binary
    jsonBinary: await helpers.prepareBinaryData(Buffer.from(jsonContent), jsonFileName, 'application/json')
  }
}];

const res  = $input.first().json;
const prev = $('Build RR Payload').item.json;

const resumeId = res.data || res.id || (typeof res === 'string' ? res.replace(/"/g, '') : null);

if (!resumeId || typeof resumeId !== 'string' || resumeId.length < 5) {
  throw new Error('RR Create: unexpected response — ' + JSON.stringify(res));
}

const rd = prev.resumeData;

const template = prev.template || 'onyx';

// Theme was randomly chosen per-candidate in Define 2 Candidate Profiles
const theme = prev.theme || {
  primary: 'rgba(26, 86, 219, 1)',
  background: 'rgba(255, 255, 255, 1)',
  text: 'rgba(26, 26, 46, 1)'
};

const patchOps = [
  { op: 'replace', path: '/metadata/template',      value: template },
  { op: 'add',     path: '/metadata/design/colors', value: theme },
  { op: 'add',     path: '/basics',                 value: rd.basics },
  { op: 'add',     path: '/summary',                value: rd.summary },
  { op: 'add',     path: '/sections/experience',    value: rd.sections.experience },
  { op: 'add',     path: '/sections/education',     value: rd.sections.education },
  { op: 'add',     path: '/sections/skills',        value: rd.sections.skills },
  { op: 'add',     path: '/sections/projects',      value: rd.sections.projects },
  { op: 'add',     path: '/sections/certifications',value: rd.sections.certifications }
];

// Inject headshot photo via public Google Drive URL
if (prev.photoUrl) {
  patchOps.push({
    op: 'add',
    path: '/picture',
    value: {
      url: prev.photoUrl,
      hidden: false,
      size: 128,
      rotation: 0,
      aspectRatio: 1,
      borderRadius: 5,
      borderColor: 'rgba(0, 0, 0, 1)',
      borderWidth: 0,
      shadowColor: 'rgba(0, 0, 0, 0)',
      shadowWidth: 0
    }
  });
}

return [{
  json: {
    ...prev,
    resumeId,
    patchPayload: { operations: patchOps }
  }
}];

// Build the payload for Reactive Resume CREATE API
// POST /api/openapi/resumes → returns resume ID
const data = $input.first().json;
const slug = data.slug || data.candidateName.toLowerCase().replace(/\s+/g, '-') + '-' + Date.now();

return [{
  json: {
    ...data,
    rrCreatePayload: {
      name:           data.candidateName,
      slug:           slug,
      tags:           [data.category || 'generated'],
      withSampleData: false
    },
    slug
  }
}];

const res = $input.first().json;
const prev = $('Build LLM Call 2 Prompt').item.json;

let raw = res.textResponse || res.text || res.response || "";
raw = raw.replace(/```json\n?/gi, "").replace(/```\n?/gi, "").trim();

const fixIncompleteJson = (jsonStr) => {
    let stack = [];
    let isInsideString = false;
    let escaped = false;
    for (let i = 0; i < jsonStr.length; i++) {
        let char = jsonStr[i];
        if (char === '"' && !escaped) { isInsideString = !isInsideString; }
        escaped = (char === "\\" && !escaped);
        if (!isInsideString) {
            if (char === '{' || char === '[') stack.push(char);
            else if (char === '}' || char === ']') stack.pop();
        }
    }
    if (isInsideString) jsonStr += '"';
    while (stack.length > 0) {
        let last = stack.pop();
        jsonStr += (last === '{' ? '}' : ']');
    }
    return jsonStr;
};

const match = raw.match(/\{[\s\S]*/);
if (!match) throw new Error("LLM Call 2: No JSON found.");

let part2;
try {
    let jsonStr = fixIncompleteJson(match[0]);
    jsonStr = jsonStr.replace(/"(\w+)\s+"(?=\s*["{[\dtf\-])/g, '"$1": ');
    part2 = JSON.parse(jsonStr);
} catch (e) {
    throw new Error("LLM Call 2 Parse Error: " + e.message);
}

const p1 = prev.part1;
const b = p1.basics || {};

const basics = {
    name: b.name || "",
    headline: b.label || b.headline || "",
    email: b.email || "",
    phone: b.phone || "",
    location: [b.location?.city, b.location?.region, b.location?.country].filter(Boolean).join(", ") || b.location || "",
    website: { url: b.url?.href || "", label: b.url?.label || "" },
    customFields: []
};

const summary = {
    title: "Summary",
    columns: 1,
    hidden: false,
    content: `<div style="font-size: 10pt; font-weight: normal;">${b.summary || ""}</div>`
};

const expItems = (p1.experience || []).map(e => ({
    id: e.id || ("exp-" + Math.random().toString(36).slice(2, 7)),
    hidden: false,
    company: e.company || "",
    position: e.position || "",
    location: (typeof e.location === 'object' && e.location !== null) 
              ? [e.location.city, e.location.region, e.location.country].filter(Boolean).join(", ") 
              : (e.location || ""),
    period: e.date || e.period || "",
    website: { url: "", label: "" },
    description: (() => {
        const bullets = Array.isArray(e.summary) ? e.summary : Array.isArray(e.description) ? e.description : null;
        const text = (bullets && bullets.length) ? ("<ul>" + bullets.map(b => "<li>" + b + "</li>").join("") + "</ul>") : (e.summary || e.description || "");
        return `<div style="font-size: 10pt; font-weight: normal;">${text}</div>`;
    })()
}));

const eduItems = (p1.education || []).map(e => ({
    id: e.id || ("edu-" + Math.random().toString(36).slice(2, 7)),
    hidden: false,
    school: e.institution || "",
    degree: e.studyType || e.degree || "",
    area: e.area || e.field || "",
    location: e.location || "",
    period: e.date || e.period || "",
    grade: e.score || e.gpa || "",
    description: e.summary || ""
}));

const skillItems = (part2.skills || []).map(s => ({
    id: s.id || ("sk-" + Math.random().toString(36).slice(2, 7)),
    hidden: false,
    name: s.name || "",
    description: s.description || "",
    level: s.level || 3,
    keywords: s.keywords || [],
    icon: "",
    proficiency: ""
}));

const projItems = (part2.projects || []).map(p => ({
    id: p.id || ("pr-" + Math.random().toString(36).slice(2, 7)),
    hidden: false,
    name: p.name || "",
    description: `<div style="font-size: 10pt; font-weight: normal;">${p.description || ""}</div>`,
    period: p.date || p.period || "",
    website: { url: p.url?.href || "", label: p.url?.label || "GitHub" },
    summary: `<div style="font-size: 10pt; font-weight: normal;">${p.summary || ""}</div>`,
    keywords: p.keywords || []
}));

const certItems = (part2.certifications || []).map(c => ({
    id: c.id || ("cert-" + Math.random().toString(36).slice(2, 7)),
    hidden: false,
    title: c.name || "",
    issuer: c.issuer || "",
    date: c.date || c.period || "",
    website: { url: c.url?.href || "", label: "" },
    description: `<div style="font-size: 10pt; font-weight: normal;">${c.description || ""}</div>`
}));

const resumeData = {
    basics,
    summary,
    sections: {
        experience: { title: "Experience", columns: 1, hidden: false, items: expItems },
        education: { title: "Education", columns: 1, hidden: false, items: eduItems },
        skills: { title: "Skills", columns: 2, hidden: false, items: skillItems },
        projects: { title: "Projects", columns: 1, hidden: false, items: projItems },
        certifications: { title: "Certifications", columns: 1, hidden: false, items: certItems }
    }
};

const slug = prev.name.replace(/\s+/g, "-").toLowerCase() + "-" + Date.now();

return [{
    json: {
        resumeData,
        profile: prev,
        slug,
        candidateName:   prev.name,
        candidateTitle:  prev.title,
        category:        prev.category,
        photoEnabled:    prev.photoEnabled,
        gender:          prev.gender,
        ethnicityPrompt: prev.ethnicityPrompt,
        ageDesc:         prev.ageDesc,
        template:        prev.template,
        theme:           prev.theme,
        index:           prev.index
    }
}];

