function generateEmail(first, last) {
  const sep = rand([".",  "_", ""]);
  const num = Math.random() > 0.6 ? String(randInt(1, 99)) : "";
  const domain = rand(emailDomains);
  const variants = [
    `${first.toLowerCase()}${sep}${last.toLowerCase()}${num}`,
    `${first[0].toLowerCase()}${sep}${last.toLowerCase()}${num}`,
    `${first.toLowerCase()}${sep}${last[0].toLowerCase()}${num}`
  ];
  return `${rand(variants)}@${domain}`;
}

function ageDesc(yrs) {
  if (yrs <= 3)  return `late 20s`;
  if (yrs <= 7)  return `early 30s`;
  if (yrs <= 12) return `late 30s`;
  if (yrs <= 17) return `mid 40s`;
  return `early 50s`;
}

const count = 2;
const results = [];
const usedNames = new Set();

for (let i = 0; i < count; i++) {
  let group, gender, firstName, lastName, name;
  let attempts = 0;
  do {
    group     = rand(pool);
    gender    = rand(["male","female"]);
    firstName = gender === "female" ? rand(group.firstNamesF) : rand(group.firstNamesM);
    lastName  = rand(group.lastNames);
    name      = `${firstName} ${lastName}`;
    attempts++;
  } while (usedNames.has(name) && attempts < 30);
  usedNames.add(name);

  const category  = Math.random() < 0.55 ? "CS" : "Engineering";
  const specialty = category === "CS" ? rand(csSpecialties) : rand(engSpecialties);
  const title     = category === "CS" ? rand(csTitles)      : rand(engTitles);
  const yearsExp  = category === "CS" ? randInt(1, 16) : randInt(2, 20);
  const location  = rand(locations);
  const email     = generateEmail(firstName, lastName);
  const phone     = `+1-${randInt(201,999)}-${randInt(200,999)}-${randInt(1000,9999)}`;

  const rrTemplates = [
    'azurill','bronzor','chikorita','ditgar','ditto','gengar','glalie',
    'kakuna','leafish','nosepass','onyx','pikachu','rhyhorn','meowth'
  ];
  const palettes = [
    'rgba(26, 86, 219, 1)', // Blue
    'rgba(14, 159, 110, 1)', // Emerald
    'rgba(126, 58, 242, 1)', // Violet
    'rgba(227, 160, 8, 1)', // Amber
    'rgba(224, 36, 36, 1)', // Crimson
    'rgba(8, 145, 178, 1)', // Cyan
    'rgba(214, 31, 105, 1)', // Rose
    'rgba(5, 122, 85, 1)', // Forest Green
    'rgba(104, 117, 245, 1)', // Indigo
    'rgba(255, 90, 31, 1)', // Burnt Orange
    'rgba(28, 100, 242, 1)', // Sapphire
    'rgba(4, 116, 129, 1)', // Teal
    'rgba(85, 33, 181, 1)', // Deep Purple
    'rgba(180, 52, 3, 1)', // Rust
    'rgba(30, 66, 159, 1)', // Navy
    'rgba(159, 18, 57, 1)', // Ruby
    'rgba(180, 83, 9, 1)', // Gold
    'rgba(3, 105, 161, 1)', // Sky Blue
    'rgba(15, 118, 110, 1)', // Dark Teal
    'rgba(124, 58, 237, 1)', // Purple
    'rgba(194, 65, 12, 1)', // Deep Orange
    'rgba(2, 132, 199, 1)', // Light Blue
    'rgba(22, 163, 74, 1)', // Green
    'rgba(220, 38, 38, 1)', // Red
    'rgba(147, 51, 234, 1)', // Fuchsia
  ];
  // Use Date.now() + index so each candidate gets a different slot AND
  // every workflow run lands on a different position in the list.
  // 137 and 97 are primes — good spread across list lengths 13 and 20.
  const template = rrTemplates[ (Math.floor(Date.now() / 10) + i * 137) % rrTemplates.length ];
  const primary   = palettes[    (Math.floor(Date.now() / 10) + i * 97)  % palettes.length    ];
  const theme     = { primary, text: 'rgba(0, 0, 0, 1)', background: 'rgba(255, 255, 255, 1)' };
  const photoEnabled = Math.random() < 0.75; // 75 % get a headshot

  results.push({ json: {
    name, firstName, lastName, gender,
    ethnicityId:     group.id,
    ethnicityPrompt: group.promptDesc,
    ageDesc:         ageDesc(yearsExp),
    template, theme,
    title, email, phone, location, specialty, yearsExp, category,
    photoEnabled, index: i
  }});
}

return results;

